      "claim": "pMap does not properly handle the case where a mapper returns pMapSkip for an item that is processed after the iterable has been marked as done, leading to incorrect result ordering.",
      "path": "index.js",
      "start_line": 130,
      "end_line": 140,
      "evidence": "const value = await mapper(element, index);

                    // Use Map to stage the index of the element.
                    if (value === pMapSkip) {
                        skippedIndexesMap.set(index, value);
                    }

                    result[index] = value;",
      "reproduction": {
        "code": "const {default: pMap, pMapSkip} = await load('./index.js');

async function* asyncIterable() {
  yield Promise.resolve(1);
  yield Promise.resolve(2);
  yield Promise.resolve(3);
}

const mapper = async (value, index) => {
  if (index === 1) {
    return pMapSkip;
  }
  return value * 2;
};

const result = await pMap(asyncIterable(), mapper);
assert.deepStrictEqual(result, [2, 6]);"
